  "crv_polyline_std": {
    "id": "crv_polyline_std",
    "name": "Polyline",
    "rhinoCommand": "_Polyline",
    "trName": "Standart Çoklu Çizgi & Yay",
    "meaning": "Ardışık Düz Çizgiler ve Dairesel Yaylar Çizme",
    "parentId": "polyline",
    "parentName": "Polyline",
    "isFlyoutSub": true,
    "isMatrixGoldDynamic": false,
    "icon": "icons/curve/crv_polyline_std.png",
    "startStep": "Çalışma Prensibi: Önce hiçbir nesne seçilmeden doğrudan Polyline simgesine tıklanır. Başlangıç noktası tıklanır (veya F4 tuşuna basılarak 0 merkezinden başlanır). Sıradaki köşeler ardışık tıklanarak profil oluşturulur (Mode=Arc seçilerek düz çizgiden kavise geçilebilir). Çizimi bitirmek için Enter'a basılır.",
    "consoleHistory": "Command: _Polyline\nStart of polyline ( PersistentClose=No )\nNext point of polyline ( PersistentClose=No  Mode=Line  Helpers=No  Undo )",
    "cmdPrompt": "Next point of polyline. Press Enter when done ( PersistentClose=No  Mode=Arc  Helpers=No  Direction  ThroughPoint  Center  Undo ):",
    "shortDesc": "Birbirine bağlı ardışık düz çizgiler ve dairesel kavisler çizer. F4 ile sıfırdan başlanabilir.",
    "mouseAction": "Sol Tık: Çizgi/yay segmenti ekler | Sağ Tık: Komutu tamamlar",
    "cmdOptions": [
      {
        "name": "PersistentClose=No",
        "desc": "PersistentClose (Kalıcı Otomatik Kapama): Açıldığında (Yes), her yeni noktada çizgiyi ilk başlangıç noktasına sanal bir kapatma hattıyla bağlar. Yüzük kesit profili çizerken profilin açık kalıp Sweep veya Solid oluşturamama hatasını %100 önler."
      },
      {
        "name": "Mode=Line",
        "desc": "Mode=Line (Düz Çizgi Modu): Standart ardışık düz doğru parçaları çizer. Bu moddayken çizgi uzunluğunu kilitlemek için 'Length' seçeneği açılır."
      },
      {
        "name": "Mode=Arc",
        "desc": "Mode=Arc (Dairesel Yay Modu): Düz çizgiden komuttan çıkmadan teğet dairesel kavise geçer. Yüzük rayının kavisli bombe geçişlerinde ve kulak yuvalarında yumuşak yaylar çizer."
      },
      {
        "name": "Direction",
        "desc": "Direction (Teğet Açısı / Doğrultu - Mode=Arc): Yayın başlangıç teğet açısını ve doğrultusunu el ile serbestçe kilitlemenizi sağlar."
      },
      {
        "name": "ThroughPoint",
        "desc": "ThroughPoint (Noktadan Geçen Yay - Mode=Arc): Çizilen dairesel yayın geçmesini istediğiniz ara referans noktayı tıklayarak kavis verir."
      },
      {
        "name": "Center",
        "desc": "Center (Merkez Noktası ile Yay - Mode=Arc): Yayın dairesel merkez noktasını belirleyerek o merkez etrafında kavis çizdirir."
      },
      {
        "name": "Helpers=No",
        "desc": "Helpers (Akıllı Çizim Kılavuzları): Açıldığında (Yes), fareyi hareket ettirirken önceki segmente tam diklik (90°) ve teğetlik dinamik uzantı çizgilerini ekranda yeşil kılavuz olarak gösterir."
      },
      {
        "name": "Length",
        "desc": "Length (Sabit Uzunluk Kilidi): Mode=Line iken sıradaki doğru segmentinin milimetrik uzunluğunu (örn: 3.50 mm) kilitler."
      },
      {
        "name": "Undo",
        "desc": "Undo (Son Noktayı Geri Al): Çizimi bozmadan sadece son tıklanan hatalı köşe noktasını bir adım geri alır."
      },
      {
        "name": "Close",
        "desc": "Close (Profili Kapat): Çizginin son ucunu başladığı ilk noktaya otomatik bağlayarak kapalı eğri (Closed Curve) yapar."
      }
    ],
    "jewelerTip": "💡 Kuyumcu Püf Noktası: Fantezi yüzük kolu kesiti veya baget taş yuvası çerçevesi çizerken kesintisiz profil kurar.",
    "ttsText": "Polyline komutu. Birbirine bağlı ardışık düz çizgiler ve dairesel yaylar çizer. Bu komut klasik temel çizim komutudur, yeşil şimşekli dinamik komutlardan değildir. Çalışma prensibi: Önce komuta tıklanır, ardından başlangıç noktası seçilir. F4 tuşuna basarak sıfır merkezinden başlayabilirsiniz. Ardından köşeler tıklanarak devam edilir. Komut satırındaki Mode=Arc seçeneği ile düz çizgiden anında dairesel kavise geçebilirsiniz. PersistentClose ise yüzük profilinin açık kalmasını engelleyerek kapalı profil oluşturur. Çizimi tamamlamak için Enter'a veya ekranda sağ tık tuşuna basın."
  },
