  "crv_freeform_control_pts": {
    "id": "crv_freeform_control_pts",
    "name": "Curve: Control Points",
    "rhinoCommand": "_Curve",
    "trName": "Kontrol Noktalı Serbest Eğri",
    "meaning": "Tıklanan Noktalar Arasına Pürüzsüz (Smooth) Çizgi Ekleme",
    "parentId": "free_form_curve",
    "parentName": "Free-Form Curve",
    "isFlyoutSub": true,
    "isMatrixGoldDynamic": false,
    "icon": "icons/curve/crv_freeform_control_pts.png",
    "startStep": "Çalışma Prensibi: Önce hiçbir nesne seçmeden doğrudan Free-Form Curve simgesine tıklanır. Başlangıç noktası tıklanır (F4 ile sıfırdan başlanabilir). Ardından eğrinin dalgalanacağı tepe ve çukur noktaları ardışık tıklanarak noktalar arasına pürüzsüz (smooth) organik çizgi örülür. Çizimi bitirmek için Enter'a basılır.",
    "consoleHistory": "Command: _Curve\nStart of curve ( Degree=3  SubDFriendly=No  Knots=Chord  PersistentClose=No  StartTangent )\nNext point ( Degree=3  SubDFriendly=No  Knots=Chord  PersistentClose=No  EndTangent  Undo )",
    "cmdPrompt": "Next point. Press Enter when done ( Degree=3  SubDFriendly=No  Knots=Chord  PersistentClose=No  EndTangent  Close  Sharp=No  Undo ):",
    "shortDesc": "Tıklanan kontrol noktalarının ağırlık merkezinden geçen pürüzsüz eğri çizer. Tıklanan noktalar arasına smooth hat örer.",
    "mouseAction": "Sol Tık: Kontrol noktalarını atar | Sağ Tık: Çizimi bitirir",
    "cmdOptions": [
      {
        "name": "Degree=3",
        "desc": "Degree=3 (Eğri Pürüzsüzlük Derecesi): Eğrinin matematiksel mertebesidir (varsayılan 3 - Kübik). Kuyumculukta en akıcı, organik ve kırılmasız lüks hatları 3. derece eğriler sağlar."
      },
      {
        "name": "SubDFriendly=No",
        "desc": "SubDFriendly (SubD & Heykel Modelleme Uyumu): Açıldığında (Yes), oluşturulan kontrol noktası yapısını Clayoo ve Rhino SubD organik modelleme ağına tam uyumlu hale getirir."
      },
      {
        "name": "Knots=Chord",
        "desc": "Knots=Chord (Düğüm / Knot Dağılımı): Noktalar arası mesafe oranına göre eğrinin gerginlik ve esneme dağılımını hesaplar (Chord, Uniform, SqrtChord)."
      },
      {
        "name": "PersistentClose=No",
        "desc": "PersistentClose (Kalıcı Otomatik Kapama): Açıldığında (Yes), çizilen her yeni noktada eğriyi başlangıç noktasına sanal olarak bağlar."
      },
      {
        "name": "StartTangent / EndTangent",
        "desc": "StartTangent / EndTangent (Teğet Başlama / Bitirme): Eğrinin başlangıç veya bitiş ucunu sahnedeki başka bir eğriye kusursuz teğet kilitler."
      },
      {
        "name": "Close",
        "desc": "Close (Profili Kapat): Eğrinin son ucunu başlangıç ucuna yumuşak bir kavisle teğet bağlayarak kapalı organik halka yapar."
      },
      {
        "name": "Sharp=No",
        "desc": "Sharp=No (Keskin Köşe / Kırık Açı): Eğer Yes yapılırsa, sıradaki noktada eğri yumuşak kavis yapmak yerine keskin sivri bir köşe kırar."
      },
      {
        "name": "Undo",
        "desc": "Undo (Son Noktayı Geri Al): Eğriyi baştan çizmeye gerek kalmadan sadece son tıklanan yanlış kontrol noktasını geri alır."
      }
    ],
    "jewelerTip": "💡 Kuyumcu Püf Noktası: Kontrol noktalarını az tutun (4-6 nokta); nokta sayısı arttıkça yüzey örülürken dalgalanma yapar.",
    "ttsText": "Curve Control Points. Tıklanılan noktalar arasına pürüzsüz ve organik çizgiler ekler. Yeşil şimşekli dinamik komutlardan değildir, klasik serbest eğri aracıdır."
  },
