// Helper function to find any command by ID
function findCurveCommand(cmdId) {
  if (!cmdId) return null;
  if (curveCommandsCatalog[cmdId]) return curveCommandsCatalog[cmdId];
  return null;
}

window.curveRibbonRows = curveRibbonRows;
window.curveFlyoutDrawers = curveFlyoutDrawers;
window.curveCommandsCatalog = curveCommandsCatalog;
window.findCurveCommand = findCurveCommand;
